SELECT product_id, unit_price_bucket, stddev_quantity FROM (SELECT product_id, CASE WHEN unit_price >= 370 THEN 'high' WHEN unit_price >= 120 THEN 'mid' ELSE 'low' END AS unit_price_bucket, ROUND(STDDEV(quantity), 2) AS stddev_quantity FROM order_items GROUP BY product_id, CASE WHEN unit_price >= 370 THEN 'high' WHEN unit_price >= 120 THEN 'mid' ELSE 'low' END) AS x WHERE stddev_quantity < 45 ORDER BY stddev_quantity DESC;
